/// Parses Windows WLAN profile XML (`WlanGetProfile` / `netsh wlan export`).
///
/// Pure Dart so it can be unit tested on every platform. The XML is machine
/// generated by Windows and locale independent, unlike `netsh` text output.
library;

import 'dart:convert';

import '../../../core/models/guest_wifi.dart';

/// Result of reading one profile.
sealed class WlanProfileResult {
  const WlanProfileResult();
}

/// The profile contained a usable plain-text key.
final class WlanProfileCredentials extends WlanProfileResult {
  const WlanProfileCredentials(this.wifi);
  final GuestWifi wifi;
}

/// Windows returned the key encrypted; reading it needs admin rights.
final class WlanProfileKeyProtected extends WlanProfileResult {
  const WlanProfileKeyProtected(
    this.ssid,
    this.security, {
    this.hidden = false,
  });
  final String ssid;
  final WifiSecurity security;
  final bool hidden;
}

/// The network cannot be shared with a QR code (for example enterprise login).
final class WlanProfileUnsupported extends WlanProfileResult {
  const WlanProfileUnsupported(this.ssid, this.authentication);
  final String ssid;
  final String authentication;
}

/// Reads [xml]; returns `null` when it is not a WLAN profile.
WlanProfileResult? parseWlanProfileXml(String xml) {
  final ssidBlock = _element(xml, 'SSID');
  final hex = ssidBlock == null ? null : _element(ssidBlock, 'hex');
  var ssid = ssidBlock == null ? null : _element(ssidBlock, 'name');
  if (hex != null && RegExp(r'^([0-9a-fA-F]{2})+$').hasMatch(hex)) {
    final bytes = [
      for (var i = 0; i < hex.length; i += 2)
        int.parse(hex.substring(i, i + 2), radix: 16),
    ];
    ssid = utf8.decode(bytes, allowMalformed: true);
  }
  ssid ??= _element(xml, 'name');
  if (ssid == null || ssid.isEmpty) return null;
  final hidden = _element(xml, 'nonBroadcast')?.toLowerCase() == 'true';
  final authentication = _element(xml, 'authentication') ?? 'open';
  final encryption = (_element(xml, 'encryption') ?? 'none').toUpperCase();
  final security = switch (authentication.toUpperCase()) {
    'OPEN' when encryption == 'NONE' => WifiSecurity.open,
    'OPEN' || 'SHARED' when encryption == 'WEP' => WifiSecurity.wep,
    'WPAPSK' || 'WPA2PSK' => WifiSecurity.wpa,
    'WPA3SAE' => WifiSecurity.sae,
    _ => null,
  };
  if (security == null) return WlanProfileUnsupported(ssid, authentication);
  if (security == WifiSecurity.open) {
    return WlanProfileCredentials(
      GuestWifi(ssid: ssid, security: security, hidden: hidden),
    );
  }
  final key = _element(xml, 'keyMaterial');
  final protected = _element(xml, 'protected')?.toLowerCase() != 'false';
  if (key == null || key.isEmpty || protected) {
    return WlanProfileKeyProtected(ssid, security, hidden: hidden);
  }
  return WlanProfileCredentials(
    GuestWifi(ssid: ssid, password: key, security: security, hidden: hidden),
  );
}

String? _element(String xml, String name) {
  final match = RegExp(
    '<(?:[A-Za-z0-9_]+:)?$name(?:\\s[^>]*)?>(.*?)</(?:[A-Za-z0-9_]+:)?$name>',
    dotAll: true,
  ).firstMatch(xml);
  final value = match?.group(1);
  return value == null ? null : _unescape(value.trim());
}

String _unescape(String value) => value
    .replaceAll('&lt;', '<')
    .replaceAll('&gt;', '>')
    .replaceAll('&quot;', '"')
    .replaceAll('&apos;', "'")
    .replaceAllMapped(
      RegExp(r'&#(x?)([0-9a-fA-F]+);'),
      (m) =>
          String.fromCharCode(int.parse(m[2]!, radix: m[1]!.isEmpty ? 10 : 16)),
    )
    .replaceAll('&amp;', '&');
